use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn pattern_char(i: nat) -> char
    decreases i,
{
    if i % 4 == 0 || i % 4 == 1 {
        'a'
    } else {
        'b'
    }
}

fn solve(n: i8) -> (result: Vec<char>)
    requires
        n >= 0,
        n as usize <= usize::MAX,
    ensures
        result.len() == n as usize,
        forall|k: int| 0 <= k < result.len() ==> result[k] == pattern_char(k as nat),
{
    let n_usize = n as usize;
    let mut result = Vec::with_capacity(n_usize);
    
    let mut i: usize = 0;
    while i < n_usize
        invariant
            0 <= i <= n_usize,
            result.len() == i,
            result.capacity() >= n_usize,
            forall|k: int| 0 <= k < i ==> result[k] == pattern_char(k as nat),
        decreases n_usize - i,
    {
        match i % 4 {
            0 | 1 => result.push('a'),
            2 | 3 => result.push('b'),
            _ => unreachable!(), // i % 4 can only be 0,1,2,3
        }
        i = i + 1;
    }
    
    result
}

}
